import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int h = in.nextInt();
        int m = in.nextInt();

        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = h;
        }

        for (int i = 0; i < m; i++) {
            int l = in.nextInt();
            int r = in.nextInt();
            int res = in.nextInt();
            l--;
            r--;
            for (int j = l; j <= r; j++) {
                if (a[j] > res) {
                    a[j] = res;
                }
            }
        }

        long ans = 0;
        for (int i = 0; i < n; i++) {
            ans += (long) a[i] * a[i];
        }

        out.println(ans);
        out.flush();
    }

    private static int minstep(byte a, byte b) {
        return min((a - b + 26) % 26, (b - a + 26) % 26);
    }

    private static int min(int a, int b) {
        return a < b ? a : b;
    }
}

